// ─── File: SafeAccountDemo.java ───
// Shows NOT IN + NULL returning nothing, and NOT EXISTS / LEFT JOIN fixes.
package com.bank.safe;

import java.util.*;
import java.util.logging.*;

public class SafeAccountDemo {
    private static final Logger log = Logger.getLogger(SafeAccountDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BankRepository repo = new BankRepository();
        SafeAccountService service = new SafeAccountService(repo);

        log.info("=== BROKEN: NOT IN with a NULL in the set ===");
        List<String> notIn = service.safeViaNotIn();
        if (notIn.isEmpty())
            log.severe("NOT IN returned 0 safe accounts (NULL in blocklist broke it!)");
        else notIn.forEach(id -> log.info("safe: " + id));

        log.info("=== SAFE: NOT EXISTS ===");
        service.safeViaNotExists().forEach(id -> log.info("safe: " + id));

        log.info("=== SAFE: LEFT JOIN ... IS NULL ===");
        service.safeViaLeftJoin().forEach(id -> log.info("safe: " + id));
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId, holderName;
    Account(String id, String name) { this.accountId = id; this.holderName = name; }
}

// ─── Would be in repository/BankRepository.java ───
class BankRepository {
    List<Account> accounts() {
        return List.of(new Account("SAV2001", "Rajesh Kumar"),
                       new Account("CUR3001", "Priya Sharma"),
                       new Account("SAV2002", "Amit Verma"));
    }
    List<String> blocklist() {
        // contains a NULL (stray bad import)
        List<String> l = new ArrayList<>();
        l.add("CUR3001"); l.add(null);
        return l;
    }
}

// ─── Would be in service/SafeAccountService.java ───
class SafeAccountService {
    private final BankRepository repo;
    SafeAccountService(BankRepository repo) { this.repo = repo; }

    // BROKEN: mirrors SQL NOT IN — a NULL in the set makes everything UNKNOWN.
    List<String> safeViaNotIn() {
        List<String> block = repo.blocklist();
        boolean hasNull = block.stream().anyMatch(Objects::isNull);
        if (hasNull) return List.of(); // SQL semantics: 0 rows
        return repo.accounts().stream()
            .filter(a -> !block.contains(a.accountId))
            .map(a -> a.accountId).toList();
    }

    // SAFE: NOT EXISTS — value inequality never involved, NULL-immune.
    List<String> safeViaNotExists() {
        List<String> block = repo.blocklist();
        return repo.accounts().stream()
            .filter(a -> block.stream().noneMatch(b -> a.accountId.equals(b)))
            .map(a -> a.accountId).toList();
    }

    // SAFE: LEFT JOIN ... IS NULL anti-join.
    List<String> safeViaLeftJoin() {
        List<String> block = repo.blocklist();
        List<String> result = new ArrayList<>();
        for (Account a : repo.accounts()) {
            // left join: find matching blocklist row (NULL-safe equals)
            boolean matched = block.stream().anyMatch(b -> a.accountId.equals(b));
            if (!matched) result.add(a.accountId); // b.account_id IS NULL
        }
        return result;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
